import{companyToProfile,currentUser,ownedCompany}from"/supabase/client.js";
import{RESET_MODULES,changeMasterKey,companySecurityStatus,configureMasterKey,masterKeyFormState,revokeDepartmentResetKey,setDepartmentResetKey}from"/security/client.js";

const $=selector=>document.querySelector(selector),error=$("[data-security-error]"),success=$("[data-security-success]"),masterForm=$("[data-master-form]"),departmentForm=$("[data-department-key-form]"),currentKeyField=$("[data-current-key-field]"),currentKeyInput=masterForm.elements.currentKey;
let company,status;
function message(text,isError=false){error.hidden=true;success.hidden=true;const box=isError?error:success;box.textContent=text;box.hidden=false}
function render(){const view=masterKeyFormState(status),masterCard=masterForm.closest("section");masterCard.querySelector("h2").textContent=view.title;$("[data-master-status]").textContent=view.statusText;masterForm.elements.confirmKey.closest(".field").querySelector("label").textContent=view.confirmationLabel;masterForm.querySelector("button").textContent=view.actionLabel;currentKeyInput.required=view.configured;currentKeyInput.disabled=!view.configured;if(view.configured){currentKeyField.hidden=false;if(!currentKeyField.isConnected)masterForm.prepend(currentKeyField)}else{currentKeyInput.value="";currentKeyField.remove()}departmentForm.querySelector("button").disabled=!view.configured;$("[data-reset-key-status]").innerHTML=RESET_MODULES.map(module=>`<p><strong>${module.label}</strong> — ${status.departmentModules.includes(module.id)?"Configured":"Not configured"}${module.executable?"":" · execution not enabled"}</p>`).join("")}
async function refresh(){status=await companySecurityStatus(company.companyId);render()}
const user=await currentUser(),profile=companyToProfile(await ownedCompany());
if(!user||!profile||profile.ownerId!==user.id){document.body.textContent="Company Owner authorization is required.";throw new Error("Owner authorization required")}
company=profile;
departmentForm.elements.moduleId.replaceChildren(...RESET_MODULES.map(module=>new Option(module.label,module.id)));
departmentForm.elements.operation.addEventListener("change",()=>{const revoke=departmentForm.elements.operation.value==="revoke";departmentForm.querySelectorAll("[data-new-reset-key]").forEach(field=>field.hidden=revoke);departmentForm.elements.newKey.required=!revoke;departmentForm.elements.confirmKey.required=!revoke});
masterForm.addEventListener("submit",async event=>{event.preventDefault();const values=Object.fromEntries(new FormData(masterForm));try{if(values.newKey!==values.confirmKey)throw new Error("New Master Key confirmation does not match.");const wasConfigured=status.masterConfigured;if(wasConfigured)await changeMasterKey(company.companyId,values.currentKey,values.newKey);else await configureMasterKey(company.companyId,values.newKey);masterForm.reset();message(wasConfigured?"Master Key changed. Department Reset Keys remain valid.":"Master Key configured.");await refresh()}catch(cause){message(cause.message||"Unable to update Company Master Key.",true)}});
departmentForm.addEventListener("submit",async event=>{event.preventDefault();const values=Object.fromEntries(new FormData(departmentForm));try{if(values.operation==="revoke")await revokeDepartmentResetKey(company.companyId,values.moduleId,values.masterKey);else{if(values.newKey!==values.confirmKey)throw new Error("Department Reset Key confirmation does not match.");await setDepartmentResetKey(company.companyId,values.moduleId,values.masterKey,values.newKey)}departmentForm.reset();departmentForm.elements.operation.dispatchEvent(new Event("change"));message(values.operation==="revoke"?"Department Reset Key revoked.":"Department Reset Key configured.");await refresh()}catch(cause){message(cause.message||"Unable to update Department Reset Key.",true)}});
try{await refresh()}catch(cause){message("Company Security is not available until the reviewed security migration is applied.",true);masterForm.querySelector("button").disabled=true;departmentForm.querySelector("button").disabled=true}
